  var commonParent = nodes.first
  for node in nodes.dropFirst() {
    if let commonParentUnwrapped = commonParent {
      commonParent = findCommonAncestorOrSelf(commonParentUnwrapped, node)
    } else {
      return nil
    }
  }
  return commonParent
}

